<?php use yii\helpers\{Html,Url};$this->title='Pilih Mata Kuliah KRS';?>
<div class="d-flex justify-content-between mb-3"><div><h1 class="mb-0">Pilih Mata Kuliah</h1><span class="text-muted"><?=Html::encode($model->student->student_nationality_number.' - '.$model->student->user->name)?></span></div><?=Html::a('Kembali ke KRS',['view','id'=>$model->id],['class'=>'btn btn-primary'])?></div><div class="card card-success card-outline"><div class="card-body"><table class="table table-bordered table-striped"><thead class="thead-dark"><tr><th></th><th>Hari/Jadwal</th><th>Kurikulum</th><th>Kode</th><th>Mata Kuliah</th><th>Kelas</th><th>SKS</th><th>Semester</th><th>Kapasitas</th><th>Sesi Kuliah</th></tr></thead><tbody><?php foreach($classes as $class):?><tr><td><?=Html::checkbox('lecture_class_ids[]',false,['value'=>$class->id,'class'=>'course-checkbox'])?></td><td><?=$class->scheduleLabel?></td><td><?=Html::encode($class->curriculum->curriculumYear->year??'-')?></td><td><?=Html::encode($class->curriculum->subject->code)?></td><td><?=Html::encode($class->curriculum->subject->name)?></td><td><?=Html::encode($class->name)?></td><td><?=$class->curriculum->subject->credits?></td><td><?=$class->curriculum->semester?></td><td><?=$class->capacity?></td><td><?=Html::encode($class->lectureSystem->name??'-')?></td></tr><?php endforeach?><?php if(!$classes):?><tr><td colspan="10" class="text-center">Tidak ada kelas yang ditawarkan.</td></tr><?php endif?></tbody></table><div class="text-right"><?=Html::button('<i class="fas fa-plus"></i> Ambil Mata Kuliah',['class'=>'btn btn-success','id'=>'add-courses'])?></div></div></div>
<?php $url=Url::to(['add-courses','id'=>$model->id]);$js=<<<'JS'
$('#add-courses').on('click',function(){var ids=$('.course-checkbox:checked').map(function(){return this.value;}).get();if(!ids.length){Swal.fire('Perhatian','Pilih minimal satu mata kuliah.','warning');return;}$.post('__ADD__',{_csrf:yii.getCsrfToken(),lecture_class_ids:ids}).done(function(r){Swal.fire(r.success?'Berhasil':'Gagal',r.message,r.success?'success':'error').then(function(){if(r.success)location='__BACK__';});});});
JS;$this->registerJs(str_replace(['__ADD__','__BACK__'],[$url,Url::to(['view','id'=>$model->id])],$js));?>
